# Virtual DualShock 4 USB over physical DualShock 4 USB (wired).
# Full passthrough: the virtual device IS the physical device, so input,
# output, and feature requests are forwarded verbatim. No BT reformatting,
# no CRC signing, no report reshaping.
#
# ⭐ WHY THIS MAP EXISTS. A cabled DS4 was being sent through
# ds4_usb_over_ds4_bt.map, which triggers on source report 0x11 while a cabled
# pad sends 0x01. Nothing parsed its input, so the pad bridged, showed as
# plugged, and did nothing in the game. Its own 0x01 report is already exactly
# what the virtual wired DS4 emits, so no translation is wanted here -- only a
# map that says so.
#
# Report IDs are left at 0, which selects the runtime's passthrough paths
# (translate_controller_input/output copy the whole report verbatim and
# ignore the copy range). The copy = lines below are required by the map
# loader's validation but are NOT used at runtime in passthrough mode.
#
# ⭐ ITS SOUND TAKES THE CABLED DUALSENSE'S PATH. A second-model DS4
# (054c:09cc) is a USB audio device on a cable: a 32 kHz stereo speaker on
# ISO OUT 0x01 and a 16 kHz mono headset microphone on ISO IN 0x82, the same
# endpoints the virtual DS4 declares (profiles/descriptors/ds4_composite.profile).
# So the wired ISO passthrough at the bottom sends Windows' speaker bytes to
# the TV as they are (MsgIsoAudio), and the TV writes them to the pad's own
# sound card; the TV sends the microphone back (MsgMicAudio) and Windows reads
# it from 0x82.
# ⚠️ THE NUMBERS ARE WHAT DIFFER FROM THE DUALSENSE'S MAP, which leaves them at
# their defaults: 4 channels at 48 kHz out, 2 at 48 kHz in. Every part of the
# wired path reads them -- how long an ISO OUT URB is held before it is
# acknowledged, which channels the gains scale, how often the microphone is
# answered and how much of it is kept. Left at the defaults, 10 ms of speaker
# sound was acknowledged after 3.3 ms, and the microphone ran six times fast.
# ⓘ A first-model DS4 (054c:05c4) has no sound card on its cable. Windows
# still sees a speaker and a microphone, because the virtual DS4 is always the
# second model, and the TV has no card to send them to.
# ⓘ The headset jack, not the speaker, is what makes that work worth doing.
# Almost no PC game drives the DS4's speaker, but the jack and its mic are
# ordinary sound devices that need no game support at all.

[map]
id = ds4_usb_over_ds4_usb
version = 1
virtual_device = ds4_usb
physical_device = ds4_usb

[usb.endpoints]
hid_in = 0x84
hid_out = 0x03
iso_out = 0x01
iso_in = 0x82

[path.input.controller_to_virtual]
trigger = physical.read
destination_length = 64
copy = source[0..63] -> destination[0..63]

[path.output.virtual_to_controller]
# ⚠️ 32, NOT 64. A DS4's USB output report 0x05 is 32 bytes, measured in this
# project's own Wireshark capture of a wired pad (docs/ds4_knowledge.md: "HID
# OUT ep 0x03 payloads are 32 bytes (not 64)"). The DualSense's is 64, so this
# is the one line that must not be copied from its map unread.
trigger = usb.endpoint.hid_out
destination_length = 32
copy = source[0..31] -> destination[0..31]

[path.control.uac1_feature_units]
# The virtual DS4's own volume and mute, answered here as ds4_usb_over_ds4_bt.map
# answers them for the same descriptor: the speaker's feature unit is 2 and
# the headset microphone's is 5. ⓘ Nothing forwards them to the pad: the TV
# sets the pad's volume itself when it opens its sound card, as it does for a
# cabled DualSense.
audio_control_interface = 0
speaker_unit = 2
headset_unit = 5
mute_control = 1
volume_control = 2
speaker.mute.default = 0
speaker.volume.default = -25600
speaker.volume.min = -25600
speaker.volume.max = 0
speaker.volume.res = 256
headset.mute.default = 0
headset.volume.default = -25600
headset.volume.min = -25600
headset.volume.max = 0
headset.volume.res = 256

[path.control.uac1_endpoint_sample_freq]
# ⭐ The rate Windows reads back for each endpoint, and the one each ISO OUT
# URB's hold is worked out from (endpoint 0x01) and each microphone answer is
# timed by (endpoint 0x82). The defaults are the DualSense's 48000.
sample_freq_control = 1
endpoint.0x01.default = 32000
endpoint.0x01.min = 32000
endpoint.0x01.max = 32000
endpoint.0x01.res = 0
endpoint.0x82.default = 16000
endpoint.0x82.min = 16000
endpoint.0x82.max = 16000
endpoint.0x82.res = 0

[path.iso.virtual_to_physical_stream]
# wired: skip the Bluetooth pipeline, send raw PCM via MsgIsoAudio.
# Comment MUST stay on its own line -- the INI parser does not strip
# trailing comments, so an inline one becomes part of the value and the
# flag silently reads false.
passthrough = true
# The speaker stream, ISO OUT 0x01: two channels, both sound. ⓘ A DualSense's
# has four, and its third and fourth are haptics; a DS4 has none.
sample_rate = 32000
channels = 2

[path.iso.physical_to_virtual_stream]
# The headset microphone, ISO IN 0x82: one channel. Its rate is
# endpoint.0x82.default above. The default is the DualSense's two.
channels = 1

[advertise]
controller_name = DualShock 4 (Wired)
vendor = Sony
rumble = true
leds = true
adaptive_triggers = false
haptics = false
audio_output = true
audio_input = true
battery = true
